sys_script_client.script:
function onLoad() {

    if (g_form.isNewRecord()) {

        var ga = new GlideAjax('GetEmailAddress');
        ga.addParam('sysparm_name', 'getCurrentUserEmail');
        ga.getXMLAnswer(setEmail);
	}

	function setEmail(answer) {
		g_form.setValue('u_requested_for_email', answer);
	}
}
